import java.util.Arrays;

public class SortingTour {
    static long comparisons;

    static boolean less(int a, int b) { comparisons++; return a < b; }

    static void bubble(int[] a) {
        for (int end = a.length - 1; end > 0; end--) {
            boolean swapped = false;
            for (int i = 0; i < end; i++) {
                if (less(a[i + 1], a[i])) { int t = a[i]; a[i] = a[i + 1]; a[i + 1] = t; swapped = true; }
            }
            if (!swapped) return;   // already sorted: stop early
        }
    }

    static void mergeSort(int[] a, int lo, int hi) {   // sorts a[lo..hi)
        if (hi - lo < 2) return;
        int mid = (lo + hi) / 2;
        mergeSort(a, lo, mid);
        mergeSort(a, mid, hi);
        int[] merged = new int[hi - lo];
        int i = lo, j = mid, k = 0;
        while (i < mid && j < hi) merged[k++] = less(a[j], a[i]) ? a[j++] : a[i++];
        while (i < mid) merged[k++] = a[i++];
        while (j < hi) merged[k++] = a[j++];
        System.arraycopy(merged, 0, a, lo, merged.length);
    }

    static void quickSort(int[] a, int lo, int hi) {   // Lomuto partition, last element as pivot
        if (lo >= hi) return;
        int pivot = a[hi], store = lo;
        for (int i = lo; i < hi; i++) {
            if (less(a[i], pivot)) { int t = a[i]; a[i] = a[store]; a[store] = t; store++; }
        }
        int t = a[hi]; a[hi] = a[store]; a[store] = t;
        quickSort(a, lo, store - 1);
        quickSort(a, store + 1, hi);
    }

    public static void main(String[] args) {
        int[] data = {29, 3, 72, 15, 8, 41, 66, 3, 50, 21, 94, 37};
        System.out.println("input: " + Arrays.toString(data));
        String[] names = {"bubble", "merge", "quick"};
        for (String name : names) {
            int[] copy = data.clone();
            comparisons = 0;
            switch (name) {
                case "bubble" -> bubble(copy);
                case "merge" -> mergeSort(copy, 0, copy.length);
                default -> quickSort(copy, 0, copy.length - 1);
            }
            System.out.printf("%-7s %s  comparisons=%d%n", name, Arrays.toString(copy), comparisons);
        }
        System.out.println("n = 12: n^2/2 = 72 versus n*log2(n) = about 43");
    }
}

