        return
    mid = (lo + hi) // 2
    merge_sort(a, lo, mid)
    merge_sort(a, mid, hi)
    merged, i, j = [], lo, mid
    while i < mid and j < hi:
        if less(a[j], a[i]):
            merged.append(a[j])
            j += 1
        else:
            merged.append(a[i])
            i += 1
    merged += a[i:mid] + a[j:hi]
    a[lo:hi] = merged


