        return
    pivot, store = a[hi], lo
    for i in range(lo, hi):
        if less(a[i], pivot):
            a[i], a[store] = a[store], a[i]
            store += 1
    a[hi], a[store] = a[store], a[hi]
    quick_sort(a, lo, store - 1)
    quick_sort(a, store + 1, hi)


