import java.util.Arrays;

public class RadixSort {
    static void countingPassByDigit(int[] a, int place) {
        int[] count = new int[10];
        for (int value : a) count[(value / place) % 10]++;
        for (int d = 1; d < 10; d++) count[d] += count[d - 1];   // end position of each digit
        int[] out = new int[a.length];
        for (int i = a.length - 1; i >= 0; i--) {                // right to left keeps it stable
            int digit = (a[i] / place) % 10;
            out[--count[digit]] = a[i];
        }
        System.arraycopy(out, 0, a, 0, a.length);
    }

    public static void main(String[] args) {
        int[] a = {170, 45, 75, 90, 802, 24, 2, 66};
        System.out.println("input:          " + Arrays.toString(a));
        int max = Arrays.stream(a).max().getAsInt();
        String[] names = {"ones", "tens", "hundreds"};
        int pass = 0;
        for (int place = 1; max / place > 0; place *= 10) {
            countingPassByDigit(a, place);
            System.out.printf("by %-9s -> %s%n", names[pass++] + ":", Arrays.toString(a));
        }
        System.out.println(pass + " passes for " + String.valueOf(max).length() + "-digit keys, no comparisons between values");
    }
}

